toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeLine(
  id: string,
  unitPriceCents: number,
  quantity: number,
  weightGrams?: number,
): CartLine {
  const product: Product = { id, name: id, unitPriceCents, weightGrams };
  return { product, quantity };
}

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any input", () => {
    const lines = [makeLine("a", 1000, 2)];
    expect(calc.computeShippingCents(lines, 2000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(10.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat rate for non-empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      const lines = [makeLine("a", 1000, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(799);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets the freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      const lines = [makeLine("a", 5000, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds the freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      const lines = [makeLine("a", 6000, 1)];
      expect(calc.computeShippingCents(lines, 6000)).toBe(0);
    });

    it("returns flat rate when subtotal is below the freeOver threshold", () => {
      const calc = new FlatShippingCalculator(799, 5000);
      const lines = [makeLine("a", 4999, 1)];
      expect(calc.computeShippingCents(lines, 4999)).toBe(799);
    });

    it("returns flat rate without freeOver configured regardless of subtotal", () => {
      const calc = new FlatShippingCalculator(799);
      const lines = [makeLine("a", 99999, 1)];
      expect(calc.computeShippingCents(lines, 99999)).toBe(799);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weight on products)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 2)];
      expect(calc.computeShippingCents(lines, 2000)).toBe(0);
    });

    it("selects the first bracket matching the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 400)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects the bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // Exactly 500g → first bracket
      const lines = [makeLine("a", 1000, 1, 500)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket just above boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket
      const lines = [makeLine("a", 1000, 1, 501)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects the heaviest bracket for weight at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 5000)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [makeLine("a", 1000, 1, 6000)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

