import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { CartConfig, CheckoutCollaborators } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker, InventoryDecision } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";

function makeProduct(
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product {
  return { id, name: id, unitPriceCents, weightGrams };
}

describe("Cart – line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts with 0 items and zero totals", () => {
    expect(cart.itemCount).toBe(0);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("adds a product", () => {
    cart.add(makeProduct("a", 500), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    const p = makeProduct("a", 500);
    cart.add(p, 2);
    cart.add(p, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(2500);
  });

  it("rejects quantity <= 0", () => {
    expect(() => cart.add(makeProduct("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(makeProduct("a", 100), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    expect(() => cart.add(makeProduct("a", 100), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    expect(() => cart.add(makeProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("removes an existing product", () => {
    cart.add(makeProduct("a", 100), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing an unknown product", () => {
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity of an existing product", () => {
    cart.add(makeProduct("a", 100), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("removes product when quantity is updated to 0", () => {
    cart.add(makeProduct("a", 100), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false); // already removed
  });

  it("throws when updating quantity of unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 5)).toThrow("not in the cart");
  });

  it("throws when updating with negative quantity", () => {
    cart.add(makeProduct("a", 100), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("throws when updating with non-integer quantity", () => {
    cart.add(makeProduct("a", 100), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clears all items", () => {
    cart.add(makeProduct("a", 100), 2);
    cart.add(makeProduct("b", 200), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(makeProduct("a", 100), 2);
    const snap = cart.snapshot();
    // Mutating the snapshot should not affect the cart
    (snap as CartLine[])[0].quantity = 999;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart – pricing pipeline", () => {
  it("computes subtotal as sum of (price * quantity)", () => {
    const cart = new Cart();
    cart.add(makeProduct("a", 1000), 2);
    cart.add(makeProduct("b", 500), 3);
    // 2*1000 + 3*500 = 3500
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(150),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(799),
    };

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(makeProduct("a", 1000), 2);

    const totals = cart.totals();

    // Subtotal = 2000
    expect(totals.subtotalCents).toBe(2000);
    // Discount policy receives the raw subtotal
    expect(discount.computeDiscountCents).toHaveBeenCalledWith(2000);
    expect(totals.discountCents).toBe(500);

    // Tax is computed on discounted subtotal (2000 - 500 = 1500)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
    expect(totals.taxCents).toBe(150);

    // Shipping receives lines and discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1500,
    );
    expect(totals.shippingCents).toBe(799);

    // Total = discounted subtotal + tax + shipping = 1500 + 150 + 799 = 2449
    expect(totals.totalCents).toBe(2449);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(makeProduct("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("clamps over-subtotal discount to the subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(5000),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(makeProduct("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    // discounted subtotal = 0, so total = 0 + tax(0) + shipping
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(makeProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(makeProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to US region when not specified", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(makeProduct("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("uses defaults (no discount, no tax, free shipping) when no config", () => {
    const cart = new Cart();
    cart.add(makeProduct("a", 1000), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3000);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(3000);
  });
});

describe("Cart – async checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
    cart.add(makeProduct("a", 1000), 2);
    cart.add(makeProduct("b", 500), 1);
  });

  it("returns totals and lines without collaborators", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2500);
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1200) // new price for "a"
        .mockResolvedValueOnce(600),  // new price for "b"
    };

    const result = await cart.checkout({ priceFetcher: fetcher });
    // 2 * 1200 + 1 * 600 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
  });

  it("throws InventoryError when inventory says not available", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      } satisfies InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toBe("discontinued");
      expect(invErr.productId).toBeDefined();
      expect(invErr.requested).toBeGreaterThan(0);
    }
  });

  it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockImplementation(
        async (productId: string, quantity: number): Promise<InventoryDecision> => {
          if (productId === "a") {
            return { available: true, availableQuantity: 1 }; // requested 2, only 1 available
          }
          return { available: true, availableQuantity: quantity };
        },
      ),
    };

    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.available).toBe(1);
    }
  });

  it("passes when inventory confirms availability", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 100,
      } satisfies InventoryDecision),
    };

    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2500);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const taxCart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    taxCart.add(makeProduct("a", 1000), 2);

    const result = await taxCart.checkout({ asyncTaxProvider });

    // subtotal = 2000, discount = 500, discountedSubtotal = 1500
    // tax = 10% of 1500 = 150
    // shipping = 300
    // total = 1500 + 150 + 300 = 1950
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(500);
    expect(result.totals.taxCents).toBe(150);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(1950);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    const taxCart = new Cart();
    taxCart.add(makeProduct("a", 1000), 1);

    await expect(
      taxCart.checkout({ asyncTaxProvider }),
    ).rejects.toThrow("tax service down");
  });

  it("propagates priceFetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("runs pipeline in order: refresh → inventory → totals", async () => {
    const callOrder: string[] = [];

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("fetch");
        return 1000;
      }),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("check");
        return { available: true, availableQuantity: 100 };
      }),
    };

    await cart.checkout({ priceFetcher: fetcher, inventoryChecker: checker });

    // All fetches should happen before any checks
    const firstCheck = callOrder.indexOf("check");
    const lastFetch = callOrder.lastIndexOf("fetch");
    expect(lastFetch).toBeLessThan(firstCheck);
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 50 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider,
    });

    // All prices refreshed to 1000: subtotal = 2*1000 + 1*1000 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    // 8% of 3000 = 240
    expect(result.totals.taxCents).toBe(240);
  });

  it("generates default InventoryError message when reason is not provided", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      } satisfies InventoryDecision),
    };

    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toContain("insufficient stock");
    }
  });
});

